      const myDid = (window.SovraCryptoVault ? window.SovraCryptoVault.getDid() : null) || (myProfile ? myProfile.did : '${masterKey.did}');
      const myName = myProfile ? (myProfile.displayName || myProfile.name) : 'Sovereign Node';
