    async function addYtComment() {
      const input = document.getElementById('newCommentInput');
      if (!input) return;
      const text = input.value.trim();
      if (!text) return;

      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;

      input.value = '';

      try {
        const resp = await fetch('/api/youtube/comment', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            videoId: v.id,
            text,
            authorName: myProfile ? myProfile.name : 'You (Verified Peer)',
            authorHandle: myProfile ? myProfile.handle.replace('@', '') : 'you_peer',
            authorAvatar: myProfile ? myProfile.avatar : 'Y',
          }),
        });
        const data = await resp.json();
        if (data.ok && data.comment) {
          if (!ytCommentsDatabase[v.id]) ytCommentsDatabase[v.id] = [];
          ytCommentsDatabase[v.id].unshift(data.comment);
          renderYtComments('top');
        }
      } catch (err) {}
    }

    function toggleReplyBox(commentId) {
      const box = document.getElementById('reply-box-' + commentId);
      if (!box) return;
      const isHidden = box.style.display === 'none' || !box.style.display;
      box.style.display = isHidden ? 'block' : 'none';
      if (isHidden) {
        const inp = document.getElementById('reply-input-' + commentId);
        if (inp) inp.focus();
      }
    }

    async function submitNestedReply(commentId) {
      const input = document.getElementById('reply-input-' + commentId);
      if (!input) return;
      const text = input.value.trim();
      if (!text) return;

      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;

      input.value = '';

      try {
        const resp = await fetch('/api/youtube/comment', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            videoId: v.id,
            parentCommentId: commentId,
            text,
            authorName: myProfile ? myProfile.name : 'You (Verified Peer)',
            authorHandle: myProfile ? myProfile.handle.replace('@', '') : 'you_peer',
            authorAvatar: myProfile ? myProfile.avatar : 'Y',
          }),
        });
        const data = await resp.json();
        if (data.ok && data.reply) {
          const comments = ytCommentsDatabase[v.id] || [];
          const parent = comments.find(c => c.id === commentId);
          if (parent) {
            if (!parent.replies) parent.replies = [];
            parent.replies.push(data.reply);
          }
          toggleReplyBox(commentId);
          renderYtComments('top');
        }
      } catch (err) {}
    }

    function toggleRepliesThread(commentId) {
      const list = document.getElementById('replies-list-' + commentId);
      const btn = document.getElementById('btn-toggle-' + commentId);
      if (!list || !btn) return;
      const isHidden = list.style.display === 'none';
      list.style.display = isHidden ? 'flex' : 'none';
      btn.innerText = isHidden ? '▴ Hide replies' : '▾ Show replies';
    }

    function likeYtComment(commentId) {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const comments = ytCommentsDatabase[v.id] || [];
      const c = comments.find(item => item.id === commentId);
      if (c) {
        c.likes++;
        const el = document.getElementById('like-cnt-' + commentId);
        if (el) el.innerText = c.likes;
        fetch('/api/youtube/comment/like', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ videoId: v.id, commentId: commentId }),
        }).catch(() => {});
      }
    }

    function likeNestedReply(commentId, replyId) {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const comments = ytCommentsDatabase[v.id] || [];
      const c = comments.find(item => item.id === commentId);
      if (c && c.replies) {
        const r = c.replies.find(item => item.id === replyId);
        if (r) {
          r.likes++;
          renderYtComments();
          fetch('/api/youtube/comment/like', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ videoId: v.id, commentId: replyId }),
          }).catch(() => {});
        }
      }
    }

