    // --- Long-Form Video Upload Handlers (YouTube / Watch Platform) ---
    function openVideoUploadModal() {
      const m = document.getElementById('videoUploadModal');
      if (m) {
        m.style.display = 'flex';
        const sel = document.getElementById('videoUploadChannelSelect');
        if (sel) {
          const myName = (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
          let opts = '<option value="personal">👤 ' + myName + '</option>';
          const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
          for (let i = 0; i < channels.length; i++) {
            opts += '<option value="' + channels[i].id + '">📢 ' + channels[i].name + ' (' + channels[i].handle + ')</option>';
          }
          sel.innerHTML = opts;
        }
      }
    }
    function closeVideoUploadModal() {
      const m = document.getElementById('videoUploadModal');
      if (m) m.style.display = 'none';
    }
    let selectedVideoUploadFile = null;
    function handleVideoFileSelected(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      selectedVideoUploadFile = file;
      const prompt = document.getElementById('videoUploadFilePrompt');
      if (prompt) prompt.innerText = '✓ Selected: ' + file.name + ' (' + (file.size / (1024 * 1024)).toFixed(1) + ' MB)';
    }
    async function submitVideoUpload() {
      const title = document.getElementById('videoUploadTitleInput').value.trim();
      const tagsStr = document.getElementById('videoUploadTagsInput').value.trim();
      if (!title) {
        alert('Please enter a video title.');
        return;
      }
      const tags = tagsStr.split(',').map(function(t) { return t.trim(); }).filter(Boolean);
      const publishBtn = document.querySelector('#videoUploadModal .action-pill-primary');
      if (publishBtn) {
        publishBtn.disabled = true;
        publishBtn.innerText = 'Publishing... ⏳';
      }

      let videoData = null;
      let mimeType = 'video/mp4';
      if (selectedVideoUploadFile) {
        mimeType = selectedVideoUploadFile.type || 'video/mp4';
        try {
          videoData = await new Promise(function(resolve, reject) {
            const reader = new FileReader();
            reader.onload = function(e) { resolve(e.target.result); };
            reader.onerror = reject;
            reader.readAsDataURL(selectedVideoUploadFile);
          });
        } catch (readErr) {
          console.warn('Error reading video file:', readErr);
        }
      }

      const payload = {
        title: title,
        tags: tags.length ? tags : ['#Sovereign', '#P2P'],
        channelName: (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Sovereign Creator',
        channelHandle: (myProfile && myProfile.handle) ? myProfile.handle : '@creator',
        videoData: videoData,
        mimeType: mimeType
      };

      try {
        const res = await fetch('/api/youtube/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const result = await res.json();
        if (result.ok && result.video) {
          const newVideo = result.video;
          if (typeof ytVideosCatalog !== 'undefined') {
            ytVideosCatalog.unshift(newVideo);
            activeYtVideoIndex = 0;
            if (typeof renderYtCurrentVideo === 'function') {
              renderYtCurrentVideo();
            }
          }
          if (typeof longFormVideosCatalog !== 'undefined') {
            longFormVideosCatalog.unshift(newVideo);
          }
          const titleEl = document.getElementById('ytVideoTitle');
          if (titleEl) titleEl.innerText = newVideo.title;
          const cidEl = document.getElementById('ytCidDisplay');
          if (cidEl) cidEl.innerText = 'CID: ' + newVideo.cid;
          const chanEl = document.getElementById('ytChannelName');
          if (chanEl) chanEl.innerText = newVideo.channelName;
          selectedVideoUploadFile = null;
          const promptEl = document.getElementById('videoUploadFilePrompt');
          if (promptEl) promptEl.innerText = 'Choose video file (MP4, MKV, WebM)';
          closeVideoUploadModal();
          showAccountToast('🎉 Video "' + title + '" published to Sovereign Watch over P2P!');
        } else {
          alert('Video upload failed: ' + (result.error || 'Unknown error'));
        }
      } catch (err) {
        console.error('Video upload network error:', err);
        alert('Failed to publish video: ' + (err.message || 'Network error'));
      } finally {
        if (publishBtn) {
          publishBtn.disabled = false;
          publishBtn.innerText = 'Publish Video 🚀';
        }
      }
    }

    // --- Profile Creator Hub Dynamic Entities Renderer ---
    function renderCreatorHubEntities() {
      const container = document.getElementById('creatorHubEntitiesContainer');
      if (!container) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);

      const allCh = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);

      // Filter strictly to entities created/owned by the active logged-in user
      const channels = allCh.filter(function(c) {
        return currentDid && c.ownerDid && c.ownerDid === currentDid;
      });
      const pages = allPg.filter(function(p) {
        return currentDid && p.ownerDid && p.ownerDid === currentDid;
      });

      let html = '<div style="font-size: 0.82rem; font-weight: 700; color: #cbd5e1; margin-bottom: 0.6rem; display: flex; align-items: center; justify-content: space-between;">' +
        '<span>📋 Your Managed Entities (' + (channels.length + pages.length) + ')</span>' +
        '<span style="font-size: 0.72rem; color: #38bdf8; font-weight: 600;">Personal Sovereign Scope</span>' +
        '</div>';

      if (channels.length === 0 && pages.length === 0) {
        const userHandle = (typeof myProfile !== 'undefined' && myProfile && myProfile.handle) ? myProfile.handle : '@creator';
        html += '<div style="background: rgba(15, 23, 42, 0.55); border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 14px; padding: 1.5rem 1rem; text-align: center; margin-top: 0.4rem;">' +
          '<div style="font-size: 1.8rem; margin-bottom: 0.4rem;">✨</div>' +
          '<div style="font-weight: 700; color: #f8fafc; font-size: 0.92rem; margin-bottom: 0.25rem;">No Personal Entities Created Yet</div>' +
          '<div style="color: #94a3b8; font-size: 0.78rem; line-height: 1.45; max-width: 440px; margin: 0 auto 1rem;">' +
            'You are operating under your personal cryptographic identity (' + userHandle + '). Network channels and test feeds are isolated in the Admin Ops Console.' +
          '</div>' +
          '<div style="display: flex; gap: 8px; justify-content: center; flex-wrap: wrap;">' +
            '<button type="button" class="btn btn-primary" onclick="openCreateChannelModal()" style="padding: 6px 14px; font-size: 0.78rem; border-radius: 8px; background: rgba(56, 189, 248, 0.2); border: 1px solid rgba(56, 189, 248, 0.45); color: #38bdf8; font-weight: 600; cursor: pointer;">+ Create Channel</button>' +
            '<button type="button" class="btn btn-secondary" onclick="openCreatePageModal()" style="padding: 6px 14px; font-size: 0.78rem; border-radius: 8px; background: rgba(192, 132, 252, 0.15); border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc; font-weight: 600; cursor: pointer;">+ Create Page</button>' +
            '<button type="button" class="btn btn-secondary" onclick="openOmniSearch(); switchSearchTab(&apos;channels&apos;);" style="padding: 6px 14px; font-size: 0.78rem; border-radius: 8px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); color: #cbd5e1; font-weight: 600; cursor: pointer;">🌐 Explore Public Channels (' + allCh.length + ')</button>' +
          '</div>' +
        '</div>';
        container.innerHTML = html;
        if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
        return;
      }

      html += '<div style="display: flex; flex-direction: column; gap: 0.5rem;">';
      for (let i = 0; i < channels.length; i++) {
        const c = channels[i];
        html += '<div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 0.5rem; flex-wrap: wrap;">' +
          '<div style="display: flex; align-items: center; gap: 10px; cursor: pointer;" data-channel-id="' + c.id + '" onclick="openChannelRoom(this.dataset.channelId)">' +
            '<div style="width: 36px; height: 36px; border-radius: 10px; background: ' + (c.bg || '#38bdf8') + '; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; color: #fff;">' + (c.avatar || '📢') + '</div>' +
            '<div>' +
              '<div style="font-weight: 700; color: #f8fafc; font-size: 0.88rem;">' + c.name + ' <span style="font-size: 0.7rem; color: #38bdf8; font-weight: 600;">' + c.handle + '</span></div>' +
              '<div style="font-size: 0.72rem; color: #94a3b8;">📢 Broadcast Channel &bull; ' + (c.count ? c.count.toLocaleString() : '0') + ' subscribers</div>' +
            '</div>' +
          '</div>' +
          '<div style="display: flex; gap: 6px; align-items: center;">' +
            '<button type="button" class="btn btn-secondary" style="padding: 5px 10px; font-size: 0.74rem; border-radius: 8px; background: rgba(56, 189, 248, 0.12); border: 1px solid rgba(56, 189, 248, 0.35); color: #38bdf8;" data-channel-id="' + c.id + '" onclick="openSpatialChannelManageSurface(this.dataset.channelId, this)">⚙️ Manage</button>' +
            '<button type="button" class="btn btn-secondary" style="padding: 5px 10px; font-size: 0.74rem; border-radius: 8px; background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.35); color: #38bdf8;" data-entity="channel:' + c.id + '" onclick="publishAsEntity(this.dataset.entity)">📢 Post As</button>' +
            '<button type="button" class="btn btn-primary" style="padding: 5px 10px; font-size: 0.74rem; border-radius: 8px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.15); color: #f1f5f9;" data-channel-id="' + c.id + '" onclick="openChannelRoom(this.dataset.channelId)">Room</button>' +
            '<button type="button" class="btn btn-danger" style="padding: 5px 8px; font-size: 0.74rem; border-radius: 8px; background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3); color: #f87171; cursor: pointer;" title="Delete this channel" data-type="channel" data-id="' + c.id + '" data-name="' + (c.name || '').replace(/"/g, '&quot;') + '" onclick="deleteEntityPrompt(this.dataset.type, this.dataset.id, this.dataset.name)">🗑️</button>' +
          '</div>' +
        '</div>';
      }

      for (let j = 0; j < pages.length; j++) {
        const p = pages[j];
        const isCurrentActive = (typeof currentActivePersona !== 'undefined' && currentActivePersona.type === 'page' && currentActivePersona.id === p.id);
        html += '<div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 0.5rem; flex-wrap: wrap;">' +
          '<div style="display: flex; align-items: center; gap: 10px;">' +
            '<div style="width: 36px; height: 36px; border-radius: 10px; background: ' + (p.bg || '#c084fc') + '; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; color: #fff;">' + (p.avatar || '🏢') + '</div>' +
            '<div>' +
              '<div style="font-weight: 700; color: #f8fafc; font-size: 0.88rem;">' + p.name + ' <span style="font-size: 0.7rem; color: #c084fc; font-weight: 600;">' + p.handle + '</span></div>' +
              '<div style="font-size: 0.72rem; color: #94a3b8;">🏢 Sovereign Page &bull; ' + (p.category || 'Entity') + '</div>' +
            '</div>' +
          '</div>' +
          '<div style="display: flex; gap: 6px; align-items: center;">' +
            '<button type="button" class="btn btn-secondary" style="padding: 5px 10px; font-size: 0.74rem; border-radius: 8px; background: rgba(192, 132, 252, 0.12); border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc;" data-page-id="' + p.id + '" onclick="openSpatialPageManageSurface(this.dataset.pageId, this)">⚙️ Manage</button>' +
            (isCurrentActive
              ? '<button type="button" class="btn btn-primary" style="padding: 5px 12px; font-size: 0.74rem; border-radius: 8px; background: rgba(34, 197, 94, 0.2); border: 1px solid rgba(34, 197, 94, 0.45); color: #4ade80;" data-persona="personal" onclick="switchToPersona(this.dataset.persona)">✓ Active</button>'
              : '<button type="button" class="btn btn-secondary" style="padding: 5px 12px; font-size: 0.74rem; border-radius: 8px; border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc; background: rgba(192, 132, 252, 0.12);" data-persona="page:' + p.id + '" onclick="switchToPersona(this.dataset.persona)">🔄 Switch</button>'
            ) +
            '<button type="button" class="btn btn-danger" style="padding: 5px 8px; font-size: 0.74rem; border-radius: 8px; background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3); color: #f87171; cursor: pointer;" title="Delete this page" data-type="page" data-id="' + p.id + '" data-name="' + (p.name || '').replace(/"/g, '&quot;') + '" onclick="deleteEntityPrompt(this.dataset.type, this.dataset.id, this.dataset.name)">🗑️</button>' +
          '</div>' +
        '</div>';
      }
      html += '</div>';

      container.innerHTML = html;
      if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
    }

    function deleteEntityPrompt(type, id, name) {
      const typeLabel = type === 'channel' ? 'Broadcast Channel' : 'Sovereign Page';
      if (!confirm('Are you sure you want to delete ' + typeLabel + ' "' + name + '"? This will remove it from the sovereign network.')) return;
      const endpoint = type === 'channel' ? '/api/social/channels/delete' : '/api/social/pages/delete';
      const payload = type === 'channel' ? { channelId: id } : { pageId: id };

      fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (data.ok) {
          if (type === 'channel' && typeof allChannelsData !== 'undefined') {
            allChannelsData = allChannelsData.filter(function(c) { return c.id !== id; });
          } else if (type === 'page' && typeof allPagesData !== 'undefined') {
            allPagesData = allPagesData.filter(function(p) { return p.id !== id; });
          }
          if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
          if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
          showAccountToast('✓ ' + typeLabel + ' deleted.');
        } else {
          alert('Failed to delete entity: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(function(err) {
        alert('Delete error: ' + err.message);
      });
    }

    // --- Instagram / Facebook Page Persona Switcher ---
    let currentActivePersona = {
      type: 'personal',
      id: 'personal',
      name: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.displayName || myProfile.name || 'Personal Profile') : 'Personal Profile'),
      handle: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.handle || '@you') : '@you'),
      avatar: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.avatar || 'S') : 'S'),
      bg: '#6366f1'
    };

    function openSwitchPersonaModal(e) {
      if (e && e.stopPropagation) e.stopPropagation();
      const m = document.getElementById('switchPersonaModal');
      if (m) {
        renderSwitchPersonaList();
        m.style.display = 'flex';
      }
    }

    function closeSwitchPersonaModal() {
      const m = document.getElementById('switchPersonaModal');
      if (m) m.style.display = 'none';
    }

    function renderSwitchPersonaList() {
      const container = document.getElementById('switchPersonaListContainer');
      if (!container) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);
      const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
      const myHandle = (typeof myProfile !== 'undefined' && myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const myAvatar = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatar) ? myProfile.avatar : 'S';
      const myAvatarDataUrl = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatarDataUrl) ? myProfile.avatarDataUrl : null;
      const isPersonalActive = (!currentActivePersona || currentActivePersona.type === 'personal');
      
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      // Strictly filter to Pages created by the active user
      const pages = allPg.filter(function(p) {
        return currentDid && p.ownerDid && p.ownerDid === currentDid;
      });

      let html = '<div style="margin-bottom: 1rem;">' +
        '<div style="font-size: 0.72rem; font-weight: 700; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.05em; margin-bottom: 0.5rem;">Personal Identity</div>' +
        '<div style="background: rgba(255,255,255,0.04); border: 1px solid ' + (isPersonalActive ? 'rgba(99, 102, 241, 0.6)' : 'rgba(255,255,255,0.08)') + '; border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 10px;">' +
          '<div style="display: flex; align-items: center; gap: 10px;">' +
            '<div style="width: 36px; height: 36px; border-radius: 50%; background: #6366f1; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 1rem; color: #fff; overflow: hidden;">' +
              (myAvatarDataUrl ? '<img src="' + myAvatarDataUrl + '" style="width:100%;height:100%;object-fit:cover;" />' : myAvatar) +
            '</div>' +
            '<div>' +
              '<div style="font-weight: 700; font-size: 0.9rem; color: #f8fafc;">' + myName + '</div>' +
              '<div style="font-size: 0.74rem; color: #94a3b8;">' + myHandle + ' &bull; Personal Account</div>' +
            '</div>' +
          '</div>' +
          '<div>' +
            (isPersonalActive 
              ? '<span class="badge" style="background: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.4); padding: 4px 10px; border-radius: 20px; font-size: 0.74rem;">✓ Active</span>'
              : '<button type="button" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.76rem; border-radius: 8px;" data-persona="personal" onclick="switchToPersona(this.dataset.persona)">Switch</button>') +
          '</div>' +
        '</div>' +
      '</div>';

      html += '<div>' +
        '<div style="font-size: 0.72rem; font-weight: 700; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.05em; margin-bottom: 0.5rem;">Sovereign Pages You Manage (' + pages.length + ')</div>';

      if (pages.length === 0) {
        html += '<div style="text-align: center; color: #64748b; font-size: 0.8rem; padding: 14px; background: rgba(255,255,255,0.02); border-radius: 10px;">No Sovereign Pages created yet. You can create a Page for your organization, business, or project!</div>';
      } else {
        html += '<div style="display: flex; flex-direction: column; gap: 0.5rem;">';
        for (let j = 0; j < pages.length; j++) {
          const p = pages[j];
          const isPageActive = (currentActivePersona && currentActivePersona.type === 'page' && currentActivePersona.id === p.id);
          html += '<div style="background: rgba(255,255,255,0.04); border: 1px solid ' + (isPageActive ? 'rgba(192, 132, 252, 0.6)' : 'rgba(255,255,255,0.08)') + '; border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 10px;">' +
            '<div style="display: flex; align-items: center; gap: 10px;">' +
              '<div style="width: 36px; height: 36px; border-radius: 10px; background: ' + (p.bg || '#c084fc') + '; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; color: #fff;">' +
                (p.avatar || '🏢') +
              '</div>' +
              '<div>' +
                '<div style="font-weight: 700; font-size: 0.9rem; color: #f8fafc;">' + p.name + '</div>' +
                '<div style="font-size: 0.74rem; color: #c084fc;">' + p.handle + ' &bull; ' + (p.category || 'Page') + '</div>' +
              '</div>' +
            '</div>' +
            '<div>' +
              (isPageActive 
                ? '<span class="badge" style="background: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.4); padding: 4px 10px; border-radius: 20px; font-size: 0.74rem;">✓ Active</span>'
                : '<button type="button" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.76rem; border-radius: 8px; border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc; background: rgba(192, 132, 252, 0.12);" data-persona="page:' + p.id + '" onclick="switchToPersona(this.dataset.persona)">Switch to Page</button>') +
            '</div>' +
          '</div>';
        }
        html += '</div>';
      }
      html += '</div>';

      container.innerHTML = html;
    }

    // Dynamic Author Persona Options Synchronizer
    function refreshComposerAuthorSelect() {
      const authorSelect = document.getElementById('composerAuthorSelect');
      if (!authorSelect) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);
      const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) 
        ? (myProfile.displayName || myProfile.name) 
        : 'Personal Profile';

      // 1. Personal Account optgroup
      let selfGroup = authorSelect.querySelector('optgroup[label*="Personal"]');
      if (!selfGroup) {
        selfGroup = document.createElement('optgroup');
        selfGroup.label = '👤 Personal Account';
        authorSelect.insertBefore(selfGroup, authorSelect.firstChild);
      }
      let selfOpt = selfGroup.querySelector('option[value="personal:self"]');
      if (!selfOpt) {
        selfOpt = document.createElement('option');
        selfOpt.value = 'personal:self';
        selfGroup.appendChild(selfOpt);
      }
      selfOpt.textContent = '👤 ' + myName;

      // 2. Sovereign Pages optgroup - strictly user-owned pages
      let pgGroup = authorSelect.querySelector('optgroup[label*="Pages"]');
      if (!pgGroup) {
        pgGroup = document.createElement('optgroup');
        pgGroup.label = '📄 Sovereign Pages';
        authorSelect.appendChild(pgGroup);
      }
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      const myPages = allPg.filter(function(p) {
        return currentDid && p.ownerDid && p.ownerDid === currentDid;
      });
      pgGroup.innerHTML = '';
      for (let i = 0; i < myPages.length; i++) {
        const opt = document.createElement('option');
        opt.value = 'page:' + myPages[i].id;
        opt.textContent = '📄 ' + myPages[i].name;
        pgGroup.appendChild(opt);
      }

      // 3. Broadcast Channels optgroup - strictly user-owned channels
      let chGroup = authorSelect.querySelector('optgroup[label*="Channels"]');
      if (!chGroup) {
        chGroup = document.createElement('optgroup');
        chGroup.label = '📢 Broadcast Channels';
        authorSelect.appendChild(chGroup);
      }
      const allCh = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const myChannels = allCh.filter(function(c) {
        return currentDid && c.ownerDid && c.ownerDid === currentDid;
      });
      chGroup.innerHTML = '';
      for (let j = 0; j < myChannels.length; j++) {
        const opt = document.createElement('option');
        opt.value = 'channel:' + myChannels[j].id;
        opt.textContent = '📢 ' + myChannels[j].name;
        chGroup.appendChild(opt);
      }
    }

    function switchToPersona(val) {
      const authorSelect = document.getElementById('composerAuthorSelect');
      const personaBar = document.getElementById('composerActivePersonaBar');
      const personaName = document.getElementById('composerActivePersonaName');
      const personaHandle = document.getElementById('composerActivePersonaHandle');
      const mainAvatar = document.getElementById('mainComposerUserAvatar');
      const composerInput = document.getElementById('dynamicPostCaption');

      if (!val || val === 'personal' || val === 'personal:self') {
        const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
        const myHandle = (typeof myProfile !== 'undefined' && myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
        const myAvatar = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatar) ? myProfile.avatar : 'S';
        const myAvatarDataUrl = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatarDataUrl) ? myProfile.avatarDataUrl : null;
        currentActivePersona = {
          type: 'personal',
          id: 'personal',
          name: myName,
          handle: myHandle,
          avatar: myAvatar,
          bg: '#6366f1'
        };

        if (authorSelect) {
          authorSelect.value = 'personal:self';
          handleComposerAuthorChange('personal:self');
        }
        if (personaBar) personaBar.style.display = 'none';
        if (mainAvatar) {
          mainAvatar.style.background = '#6366f1';
          mainAvatar.innerHTML = myAvatarDataUrl ? '<img src="' + myAvatarDataUrl + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;" />' : myAvatar;
        }
        if (composerInput) {
          composerInput.placeholder = "What's on your mind?";
        }
        showAccountToast('👤 Switched to Personal Profile (' + myHandle + ')');
      } else if (val.startsWith('page:')) {
        const pageId = val.replace('page:', '');
        const pages = (typeof allPagesData !== 'undefined' ? allPagesData : []);
        const page = pages.find(function(p) { return p.id === pageId; });
        if (page) {
          currentActivePersona = {
            type: 'page',
            id: page.id,
            name: page.name,
            handle: page.handle,
            avatar: page.avatar || '🏢',
            bg: page.bg || '#c084fc'
          };

          if (authorSelect) {
            authorSelect.value = val;
            handleComposerAuthorChange(val);
          }
          if (personaBar) {
            personaBar.style.display = 'flex';
            if (personaName) personaName.innerText = page.name;
            if (personaHandle) personaHandle.innerText = page.handle;
          }
          if (mainAvatar) {
            mainAvatar.style.background = page.bg || '#c084fc';
            mainAvatar.innerHTML = page.avatar || '🏢';
          }
          if (composerInput) {
            composerInput.placeholder = 'Post an update as ' + page.name + '...';
          }
          showAccountToast('🏢 Switched to Page: ' + page.name + ' (' + page.handle + ')');
        }
      }

      closeSwitchPersonaModal();
      if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
    }

    // --- Telegram / WhatsApp Broadcast Channel Room ---
    let activeChannelRoomId = null;

    function openChannelRoom(channelId) {
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === channelId || c.handle === channelId; });
      if (!ch) {
        showAccountToast('Channel not found');
        return;
      }
      activeChannelRoomId = ch.id;

      const avatarEl = document.getElementById('channelRoomAvatar');
      if (avatarEl) {
        avatarEl.innerText = ch.avatar || '📢';
        avatarEl.style.background = ch.bg || '#0284c7';
      }
      const nameEl = document.getElementById('channelRoomName');
      if (nameEl) nameEl.innerText = ch.name;
      const handleEl = document.getElementById('channelRoomHandle');
      if (handleEl) handleEl.innerText = ch.handle;
      const subsEl = document.getElementById('channelRoomSubs');
      if (subsEl) subsEl.innerText = (ch.count ? ch.count.toLocaleString() : '1') + ' subscribers';
      const bioEl = document.getElementById('channelRoomBioBanner');
      if (bioEl) bioEl.innerText = ch.desc || 'Decentralized broadcast channel for P2P updates.';

      const subBtn = document.getElementById('channelRoomSubBtn');
      if (subBtn) {
        subBtn.innerText = ch.isSubbed ? 'Subscribed ✓' : 'Subscribe';
        subBtn.className = ch.isSubbed ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }

      renderChannelRoomStream(ch);

      const modal = document.getElementById('channelRoomModal');
      if (modal) modal.style.display = 'flex';

      const input = document.getElementById('channelBroadcastInput');
      if (input) {
        input.value = '';
        setTimeout(function() { input.focus(); }, 200);
      }
    }

    function closeChannelRoom() {
      const modal = document.getElementById('channelRoomModal');
      if (modal) modal.style.display = 'none';
      activeChannelRoomId = null;
    }

    function toggleChannelRoomSubscribe() {
      if (!activeChannelRoomId) return;
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (!ch) return;
      ch.isSubbed = !ch.isSubbed;
      ch.count += ch.isSubbed ? 1 : -1;
      const subBtn = document.getElementById('channelRoomSubBtn');
      if (subBtn) {
        subBtn.innerText = ch.isSubbed ? 'Subscribed ✓' : 'Subscribe';
        subBtn.className = ch.isSubbed ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }
      const subsEl = document.getElementById('channelRoomSubs');
      if (subsEl) subsEl.innerText = (ch.count ? ch.count.toLocaleString() : '1') + ' subscribers';
      fetch('/api/social/channels/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ channelId: ch.id })
      }).catch(function(err) { console.warn('[Channel] Subscribe error:', err); });
      showAccountToast(ch.isSubbed ? '🔔 Subscribed to ' + ch.name : '🔕 Unsubscribed from ' + ch.name);
    }

    function renderChannelRoomStream(ch) {
      const container = document.getElementById('channelRoomStream');
      if (!container) return;
      const posts = (typeof feedPostsData !== 'undefined' ? feedPostsData : []).filter(function(p) {
        return (p.authorType === 'channel' && (p.authorEntityId === ch.id || p.authorEntityHandle === ch.handle));
      });

      if (posts.length === 0) {
        container.innerHTML = '<div style="text-align: center; padding: 2.5rem 1rem; color: #94a3b8; display: flex; flex-direction: column; align-items: center; gap: 0.75rem;">' +
          '<div style="width: 52px; height: 52px; border-radius: 16px; background: rgba(56, 189, 248, 0.15); color: #38bdf8; display: align-items: center; justify-content: center; font-size: 1.6rem; display: flex;">📢</div>' +
          '<div style="font-weight: 700; color: #f8fafc; font-size: 1.05rem;">' + ch.name + ' Broadcast Feed</div>' +
          '<div style="font-size: 0.82rem; max-width: 360px; line-height: 1.4;">This is a decentralized Telegram-style broadcast channel. Subscribers receive real-time updates directly over the peer-to-peer mesh.</div>' +
          '<div style="font-size: 0.76rem; color: #38bdf8; font-weight: 600; margin-top: 0.25rem;">Broadcast an announcement below to get started!</div>' +
        '</div>';
        return;
      }

      let html = '';
      for (let i = posts.length - 1; i >= 0; i--) {
        const p = posts[i];
        const timeStr = new Date(p.timestamp || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        html += '<div style="background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(56, 189, 248, 0.2); border-radius: 16px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px; box-shadow: 0 4px 14px rgba(0,0,0,0.3);">' +
          '<div style="display: flex; justify-content: space-between; align-items: center;">' +
            '<div style="display: flex; align-items: center; gap: 6px;">' +
              '<span class="badge" style="background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3); font-size: 0.68rem; font-weight: 700;">📢 BROADCAST</span>' +
              '<span style="font-size: 0.74rem; color: #94a3b8; font-family: monospace;">' + (p.mediaCid ? p.mediaCid.slice(0, 12) + '...' : 'Ed25519 Signed') + '</span>' +
            '</div>' +
            '<span style="font-size: 0.72rem; color: #64748b;">' + timeStr + '</span>' +
          '</div>' +
          (p.mediaImage ? '<div style="border-radius: 10px; overflow: hidden; max-height: 280px; background: #000;"><img src="' + p.mediaImage + '" style="width: 100%; max-height: 280px; object-fit: contain; display: block;" /></div>' : '') +
          '<div style="color: #f8fafc; font-size: 0.95rem; line-height: 1.5; white-space: pre-wrap; word-break: break-word;">' + (p.caption || '') + '</div>' +
          '<div style="display: flex; justify-content: space-between; align-items: center; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 6px; margin-top: 2px;">' +
            '<div style="display: flex; gap: 6px;">' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 8px; font-size: 0.72rem; border-radius: 12px;" data-msg="❤️ Liked broadcast!" onclick="showAccountToast(this.dataset.msg)">❤️ ' + (p.likesCount || 0) + '</button>' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 8px; font-size: 0.72rem; border-radius: 12px;" data-msg="🚀 Boosted to local peers!" onclick="showAccountToast(this.dataset.msg)">🚀 Boost</button>' +
            '</div>' +
            '<span style="font-size: 0.7rem; color: #38bdf8;">✓ P2P Relayed</span>' +
          '</div>' +
        '</div>';
      }
      container.innerHTML = html;
      container.scrollTop = container.scrollHeight;
    }

    let channelPhotoDataUrl = null;
    function triggerChannelPhotoUpload() {
      const fileInput = document.getElementById('channelPhotoFileInput');
      if (fileInput) fileInput.click();
    }
    function handleChannelPhotoFile(e) {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(evt) {
        channelPhotoDataUrl = evt.target.result;
        const previewWrap = document.getElementById('channelPhotoPreviewWrap');
        const previewImg = document.getElementById('channelPhotoPreviewImg');
        if (previewWrap && previewImg) {
          previewImg.src = channelPhotoDataUrl;
          previewWrap.style.display = 'flex';
        }
      };
      reader.readAsDataURL(file);
    }
    function clearChannelPhotoUpload() {
      channelPhotoDataUrl = null;
      const previewWrap = document.getElementById('channelPhotoPreviewWrap');
      if (previewWrap) previewWrap.style.display = 'none';
      const fileInput = document.getElementById('channelPhotoFileInput');
      if (fileInput) fileInput.value = '';
    }

    function submitChannelBroadcast() {
      if (!activeChannelRoomId) return;
      const input = document.getElementById('channelBroadcastInput');
      const text = input ? input.value.trim() : '';
      if (!text && !channelPhotoDataUrl) {
        alert('Please enter a message or attach a photo to broadcast.');
        return;
      }
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (!ch) return;

      const payload = {
        caption: text,
        postType: 'text',
        authorType: 'channel',
        authorEntityId: ch.id,
        authorBadge: '📢 Channel',
        authorEntityHandle: ch.handle,
        mediaImage: channelPhotoDataUrl || undefined,
      };

      fetch('/api/feed/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + (localStorage.getItem('sovra_session_token') || '')
        },
        body: JSON.stringify(payload)
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (data.ok && data.post) {
          if (typeof feedPostsData !== 'undefined') {
            feedPostsData.unshift(data.post);
          }
          if (input) input.value = '';
          clearChannelPhotoUpload();
          renderChannelRoomStream(ch);
          if (typeof renderFeedPosts === 'function') renderFeedPosts();
          showAccountToast('📢 Broadcast dispatched to ' + ch.name + ' subscribers!');
        } else {
          alert('Broadcast failed: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(function(err) {
        console.error('[Channel] Broadcast error:', err);
        alert('Broadcast failed: ' + err.message);
      });
    }

    function publishAsEntity(val) {
      if (val && val.startsWith('channel:')) {
        openChannelRoom(val.replace('channel:', ''));
      } else if (val && val.startsWith('page:')) {
        switchToPersona(val);
        switchTab('feed');
      } else {
        switchToPersona('personal');
        switchTab('feed');
      }
    }

    // --- Feed Post Options & Actions ---
    function openPostOptionsModal(postId, author, cid) {
      activeTargetPost = { id: postId, author: author, cid: cid };
      const m = document.getElementById('postOptionsModal');
      if (m) m.style.display = 'flex';
    }
    function closePostOptionsModal() {
      const m = document.getElementById('postOptionsModal');
      if (m) m.style.display = 'none';
    }
    function triggerCopyPostLink() {
      const link = window.location.origin + '/#card-' + activeTargetPost.id;
      copyToClipboard(link, function() {
        showAccountToast('🔗 Post link copied to clipboard!');
      });
      closePostOptionsModal();
    }
    function triggerShareFromModal() {
      closePostOptionsModal();
      shareFeedPost(activeTargetPost.id, activeTargetPost.cid);
    }
    function triggerNotInterestedFromModal() {
      const postId = activeTargetPost.id;
      closePostOptionsModal();
      handleFeedDislike(postId);
    }
    function triggerCopyPostCid() {
      const cid = activeTargetPost.cid || 'bafybeic' + activeTargetPost.id;
      copyToClipboard('ipfs://' + cid, function() {
        showAccountToast('🛡️ Cryptographic IPFS CID copied: ' + cid.slice(0, 16) + '...');
      });
      closePostOptionsModal();
    }
    function triggerMuteFromModal() {
      closePostOptionsModal();
      showAccountToast('🔕 Muted @' + activeTargetPost.author);
    }
    function triggerBlockFromModal() {
      closePostOptionsModal();
      const card = document.getElementById('card-' + activeTargetPost.id);
      if (card) card.style.display = 'none';
      showAccountToast('🚫 Blocked @' + activeTargetPost.author);
    }
    function triggerDeleteFromModal() {
      closePostOptionsModal();
      const card = document.getElementById('card-' + activeTargetPost.id);
      if (card) {
        card.style.opacity = '0';
        card.style.transform = 'scale(0.95)';
        card.style.transition = 'all 0.3s ease';
        setTimeout(function() { card.remove(); }, 320);
      }
      feedPostsData = feedPostsData.filter(function(p) { return p.id !== activeTargetPost.id; });
      updateProfileDynamicStats();
      fetch('/api/feed/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ postId: activeTargetPost.id })
      }).catch(function(err) { console.warn('[Feed] Delete error:', err); });
      showAccountToast('🗑️ Post deleted');
    }

    // --- Dislike Handler ---
    function handleFeedDislike(postId) {
      const card = document.getElementById('card-' + postId);
      if (card) {
        card.style.opacity = '0.45';
        card.style.transition = 'opacity 0.3s';
      }
      showAccountToast('👎 Post hidden. We will show fewer posts like this.');
    }

    // --- Repost & Quote Post ---
    function openRepostModal(postId) {
      activeTargetPost.id = postId;
      const m = document.getElementById('repostModal');
      if (m) {
        m.style.display = 'flex';
        document.getElementById('repostCommentaryInput').value = '';
      }
    }
    function closeRepostModal() {
      const m = document.getElementById('repostModal');
      if (m) m.style.display = 'none';
    }
    function submitInstantRepost() {
      closeRepostModal();
      showAccountToast('🔁 Reposted to your profile');
    }
    function submitQuoteRepost() {
      const commentary = document.getElementById('repostCommentaryInput').value.trim();
      closeRepostModal();
      showAccountToast('✍️ Quote post published');
    }

    // --- Safety & Dispute Report ---
    function triggerSafetyReportModal() {
      closePostOptionsModal();
      const m = document.getElementById('safetyReportModal');
      if (m) m.style.display = 'flex';
    }
